param([string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$runner=Join-Path $PSScriptRoot 'run-experiment-1-23-core.ps1';$result=Join-Path $root 'backend\experiments\results\experiment-1-23';$runs=@(@{c='BASELINE';i='001'},@{c='REMEDIATION';i='001'},@{c='BASELINE';i='002'},@{c='REMEDIATION';i='002'},@{c='BASELINE';i='003'},@{c='REMEDIATION';i='003'});New-Item -ItemType Directory -Force (Join-Path $result 'plan')|Out-Null;$failure=$null
if($ExecutionMode-eq'PLAN'){foreach($r in $runs){& powershell -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode PLAN};$ledger=[ordered]@{experiment='Experiment 1-23';runDate=$RunDate;executionMode='PLAN';requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=0;completedRuns=0;failedRuns=0;notStartedRuns=@($runs|ForEach-Object{"RUN-$RunDate-EXP123-$($_.c)-$($_.i)"});warmup=0;k6=0;core=0;executionStatus='NOT_RUN'};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan\runner-readiness.json') -Encoding UTF8;'EXP123_PLAN_READY';exit 0}
foreach($r in $runs){try{& powershell -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode EXECUTE;if($LASTEXITCODE){throw "core exit $LASTEXITCODE"}}catch{$failure=$_;break}}
$states=@($runs|ForEach-Object{$id="RUN-$RunDate-EXP123-$($_.c)-$($_.i)";$dir=Join-Path $result "core\$id";[ordered]@{runId=$id;started=Test-Path $dir;completed=Test-Path (Join-Path $dir 'COMPLETED');failed=Test-Path (Join-Path $dir 'EXECUTION_FAILED');coreInvoked=Test-Path (Join-Path $dir 'execution-summary.json')}});$ledger=[ordered]@{experiment='Experiment 1-23';runDate=$RunDate;executionMode='EXECUTE';requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=@($states|Where-Object started).Count;completedRuns=@($states|Where-Object completed).Count;failedRuns=@($states|Where-Object failed).Count;notStartedRuns=@($states|Where-Object{-not$_.started}|ForEach-Object runId);warmup=0;k6=0;core=@($states|Where-Object coreInvoked).Count;executionStatus=if($failure){'FAILED'}else{'INCOMPLETE'};runStates=$states};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan\runner-readiness.json') -Encoding UTF8;if($failure){throw $failure}
